import networkx as nx
from networkx.algorithms.flow import preflow_push, edmonds_karp
G = nx.DiGraph()
G.add_edge('x','a',capacity=3.0); G.add_edge('a','y',capacity=3.0)
for f in [nx.maximum_flow, nx.maximum_flow_value, nx.minimum_cut, nx.minimum_cut_value]:
    for kw in [dict(flow_func=preflow_push, cutoff=1), dict(flow_func=preflow_push, cutoff=None), dict(cutoff=1)]:
        try:
            print(f.__name__, kw, f(G,'x','y',**kw))
        except Exception as e:
            print(f.__name__, kw, 'EXC', type(e).__name__, e)
"

