import itertools, random
import networkx as nx

def brute_gbc(G, C, normalized=True, weight=None, endpoints=False):
    C = set(C)
    nodes = list(G)
    total = 0.0
    for s in nodes:
        for t in nodes:
            if s == t:
                continue
            if not G.is_directed() and not (nodes.index(s) < nodes.index(t)):
                continue
            if not endpoints and (s in C or t in C):
                continue
            try:
                paths = list(nx.all_shortest_paths(G, s, t, weight=weight))
            except nx.NetworkXNoPath:
                continue
            through = sum(1 for p in paths if any(x in C for x in p))
            total += through / len(paths)
    if normalized:
        v, c = len(G), len(C)
        if G.is_directed():
            denom = (v - c) * (v - c - 1)
        else:
            denom = (v - c) * (v - c - 1) / 2
        total = total / denom if denom else 0.0
    return total

random.seed(1)
bad = 0
for trial in range(400):
    n = random.randint(3, 9)
    p = random.uniform(0.2, 0.7)
    directed = random.random() < 0.5
    G = nx.gnp_random_graph(n, p, seed=trial, directed=directed)
    weighted = random.random() < 0.5
    if weighted:
        for u, v in G.edges():
            G[u][v]["weight"] = random.randint(1, 3)
    k = random.randint(1, max(1, n - 2))
    C = random.sample(list(G), k)
    endpoints = random.random() < 0.5
    normalized = random.random() < 0.5
    if normalized and endpoints:
        normalized = False
    w = "weight" if weighted else None
    try:
        got = nx.group_betweenness_centrality(G, C, normalized=normalized, weight=w, endpoints=endpoints)
    except Exception as e:
        got = f"EXC {type(e).__name__}: {e}"
    exp = brute_gbc(G, C, normalized=normalized, weight=w, endpoints=endpoints)
    if isinstance(got, str) or abs(got - exp) > 1e-9:
        bad += 1
        if bad <= 12:
            print(f"trial={trial} n={n} dir={directed} w={weighted} ep={endpoints} norm={normalized} C={C} edges={sorted(G.edges(data='weight'))}\n   got={got} exp={exp}")
print("bad", bad, "of 400")
