import random
import numpy as np
import networkx as nx

def ref_cfc(G, weight=None):
    nodes = list(G)
    L = nx.laplacian_matrix(G, nodelist=nodes, weight=weight).toarray().astype(float)
    Lp = np.linalg.pinv(L)
    n = len(nodes)
    res = {}
    for i, v in enumerate(nodes):
        s = sum(Lp[i, i] + Lp[j, j] - 2 * Lp[i, j] for j in range(n) if j != i)
        res[v] = 1 / s
    return res

bad = 0
for trial in range(200):
    n = random.randint(2, 12)
    G = nx.connected_watts_strogatz_graph(n, min(n - 1, 2) if n > 2 else 1, 0.3, seed=trial) if n > 3 else nx.path_graph(n)
    weighted = random.random() < 0.5
    if weighted:
        for u, v in G.edges():
            G[u][v]["weight"] = random.uniform(0.5, 3)
    # relabel to strings sometimes
    if random.random() < 0.5:
        G = nx.relabel_nodes(G, {u: f"n{u}" for u in G})
    for solver in ["full", "lu", "cg"]:
        try:
            got = nx.current_flow_closeness_centrality(G, weight="weight" if weighted else None, solver=solver)
        except Exception as e:
            got = e
        exp = ref_cfc(G, weight="weight" if weighted else None)
        if isinstance(got, Exception) or any(abs(got[k] - exp[k]) > 1e-5 for k in exp):
            bad += 1
            if bad < 6:
                print(trial, solver, weighted, got, exp)
print("bad", bad)
