import random, math
import networkx as nx

def ref_closeness(G, u, distance=None, wf=True):
    N = len(G)
    # inward distances: d(v, u) for all v that reach u
    dists = {}
    for v in G:
        try:
            d = nx.shortest_path_length(G, v, u, weight=distance)
            dists[v] = d
        except nx.NetworkXNoPath:
            pass
    r = len(dists)  # includes u itself
    tot = sum(dists.values())
    if r <= 1 or N <= 1:
        return 0.0
    if tot == 0:
        return math.inf
    c = (r - 1) / tot
    if wf:
        c *= (r - 1) / (N - 1)
    return c

