import random, itertools, sys
import networkx as nx

def brute_kcomps(G):
    nodes = list(G)
    n = len(nodes)
    conn = {}
    for r in range(2, n + 1):
        for S in itertools.combinations(nodes, r):
            H = G.subgraph(S)
            if not nx.is_connected(H):
                continue
            conn[frozenset(S)] = nx.node_connectivity(H)
    res = {}
    if not conn:
        return res
    maxk = max(conn.values())
    for k in range(1, maxk + 1):
        cands = [S for S, c in conn.items() if c >= k and len(S) > k]
        maximal = [S for S in cands if not any(S < T for T in cands)]
        if maximal:
            res[k] = {S for S in maximal}
    return res

def norm(kc):
    return {k: {frozenset(c) for c in comps} for k, comps in kc.items() if comps}

