import random, itertools, sys
import networkx as nx

def brute_k_edge_components(G, k):
    # nodes u~v iff local edge connectivity in G >= k (equivalence relation)
    nodes = list(G)
    comps = []
    seen = set()
    for u in nodes:
        if u in seen: continue
        comp = {u}
        for v in nodes:
            if v != u and v not in seen:
                if nx.edge_connectivity(G, u, v) >= k:
                    comp.add(v)
        seen |= comp
        comps.append(frozenset(comp))
    return set(comps)

def brute_k_edge_subgraphs(G, k):
    nodes = list(G)
    cands = []
    for r in range(1, len(nodes) + 1):
        for S in itertools.combinations(nodes, r):
            H = G.subgraph(S)
            if r == 1 or (nx.is_connected(H) and nx.edge_connectivity(H) >= k):
                cands.append(frozenset(S))
    maximal = {S for S in cands if not any(S < T for T in cands)}
    return maximal

random.seed(int(sys.argv[1]))
bad = 0
for trial in range(int(sys.argv[2])):
    n = random.randint(2, 9)
    directed = random.random() < 0.3
    G = nx.gnp_random_graph(n, random.uniform(0.3, 0.8), seed=random.randint(0, 10**6), directed=directed)
    for k in range(1, 5):
        got = {frozenset(c) for c in nx.k_edge_components(G, k)}
        if not directed:
            exp = brute_k_edge_components(G, k)
            if got != exp:
                bad += 1
                print("kec", trial, k, sorted(G.edges()), got, exp)
            got2 = {frozenset(c) for c in nx.k_edge_subgraphs(G, k)}
            exp2 = brute_k_edge_subgraphs(G, k)
            if got2 != exp2:
                bad += 1
                print("kes", trial, k, sorted(G.edges()), got2, exp2)
