import random, itertools
import networkx as nx
from networkx.algorithms import approximation as apx

def brute_kappa(G):
    n = len(G)
    nodes = list(G)
    # smallest set whose removal makes G not strongly connected or trivial
    for k in range(0, n - 1):
        for S in itertools.combinations(nodes, k):
            H = G.subgraph(set(nodes) - set(S))
            if len(H) < 2:
                continue
            if not nx.is_strongly_connected(H):
                return k
    return n - 1

random.seed(5)
bad = 0; apx_err = 0
for trial in range(300):
    n = random.randint(3, 7)
    G = nx.gnp_random_graph(n, random.uniform(0.4, 0.95), seed=trial, directed=True)
    if not nx.is_weakly_connected(G):
        continue
    k = nx.node_connectivity(G)
    b = brute_kappa(G)
    if k != b:
        bad += 1
        if bad < 4: print("node_connectivity", trial, k, b, sorted(G.edges()))
    try:
        apx.node_connectivity(G)
    except Exception as e:
        apx_err += 1
print("bad", bad, "approx errors", apx_err)
