import random, itertools, sys
sys.path.insert(0, "/tmp/work")
import networkx as nx
from kcomp_brute import brute_kcomps, norm
from networkx.algorithms import flow
funcs = [flow.boykov_kolmogorov, flow.dinitz, flow.edmonds_karp, flow.preflow_push, flow.shortest_augmenting_path]
random.seed(int(sys.argv[1]))
bad = dup = 0
for trial in range(int(sys.argv[2])):
    n = random.randint(1, 11)
    if random.random() < 0.4:
        G = nx.gnp_random_graph(n, random.uniform(0.2, 0.95), seed=random.randint(0, 10**6))
    else:
        G = nx.Graph()
        offset = 0
        for b in range(random.randint(1, 4)):
            size = random.randint(2, 6)
            block = list(range(offset, offset + size))
            G.add_nodes_from(block)
            for u, v in itertools.combinations(block, 2):
                if random.random() < 0.8:
                    G.add_edge(u, v)
            offset += size - random.randint(0, 3)
        G = nx.convert_node_labels_to_integers(G)
    if len(G) > 12:
        continue
    raw = nx.k_components(G, flow_func=random.choice(funcs))
    for k, comps in raw.items():
        if len(comps) != len({frozenset(c) for c in comps}):
            dup += 1
    got = norm(raw)
    exp = norm(brute_kcomps(G))
    if got != exp:
        bad += 1
        if bad < 4:
            print("trial", trial, sorted(G.edges()))
            for k in sorted(set(exp) | set(got)):
                if exp.get(k) != got.get(k):
                    print("  k", k, "exp", [sorted(c) for c in exp.get(k, [])], "got", [sorted(c) for c in got.get(k, [])])
